//! Support items required by this crate's macros and by code generated by `assertr-macros`.
//!
//! Everything reachable from this module is a private implementation detail: it is
//! `#[doc(hidden)]`, exempt from semver guarantees, and must never be named directly. The macros
//! reach it through `$crate`, so no import is ever needed at a call site.

pub mod assert_that_macro;
#[cfg(feature = "fluent")]
pub mod fluent_expressions;
pub(crate) mod partial_match;

use crate::{AssertThat, assertions::core::pattern::Pattern, mode::Mode};

/// Records the source expression of a chain. Called by `assert_that!`, `assert_that_owned!`, and
/// code generated by `#[fluent_expressions]`.
#[must_use]
pub fn with_expression<'t, T, M: Mode, R>(
    chain: AssertThat<'t, T, M, R>,
    expression: &'static str,
) -> AssertThat<'t, T, M, R> {
    chain.with_expression(expression)
}

/// Constructor behind [`pattern!`](crate::pattern).
///
/// [`Pattern`] has no public constructor: building one by hand would let the rendered pattern
/// source text and the predicate disagree, which the macro guarantees cannot happen.
#[must_use]
pub fn new_pattern<P>(description: &'static str, predicate: P) -> Pattern<P> {
    Pattern::new(description, predicate)
}

/// Empty tail of a macro-generated heterogeneous list.
#[derive(Clone, Copy)]
pub struct Nil;
/// One element of a macro-generated heterogeneous list.
#[derive(Clone, Copy)]
pub struct Cons<H, T>(pub H, pub T);

/// Formats the elements of a macro-generated list, so it prints like an array of matchers.
pub trait ListEntries {
    /// Adds this node's elements to `list`.
    fn entries(&self, list: &mut core::fmt::DebugList<'_, '_>);
}

impl ListEntries for Nil {
    fn entries(&self, _: &mut core::fmt::DebugList<'_, '_>) {}
}

impl<H: core::fmt::Debug, T: ListEntries> ListEntries for Cons<H, T> {
    fn entries(&self, list: &mut core::fmt::DebugList<'_, '_>) {
        list.entry(&self.0);
        self.1.entries(list);
    }
}

impl core::fmt::Debug for Nil {
    fn fmt(&self, formatter: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        formatter.debug_list().finish()
    }
}

impl<H: core::fmt::Debug, T: ListEntries> core::fmt::Debug for Cons<H, T> {
    fn fmt(&self, formatter: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        let mut list = formatter.debug_list();
        self.entries(&mut list);
        list.finish()
    }
}

#[cfg(feature = "partial")]
pub use assertr_macros::__partial as partial;
/// Constructor behind `partial!` field selection.
pub fn field<A: ?Sized, T: ?Sized, F, M>(
    projection: F,
    matcher: M,
    path: crate::failure::PathSegment,
) -> crate::matchers::Field<A, T, F, M>
where
    F: for<'a> Fn(&'a A) -> Option<&'a T>,
{
    crate::expectation::field::projected(projection, matcher, path)
}
#[doc(hidden)]
pub use partial_match::PartialMatch;
pub use partial_match::partial_match;
